def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    obj_cells=set()
    centers=[]
    for r in range(1,H-1):
        for c in range(1,W-1):
            if g[r][c]==2 and all(g[r+dr][c+dc]==3 for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)):
                centers.append((r,c))
                for dr in(-1,0,1):
                    for dc in(-1,0,1): obj_cells.add((r+dr,c+dc))
    hlines=[r for r in range(H) if all(g[r][c]==2 or (r,c) in obj_cells for c in range(W))]
    vlines=[c for c in range(W) if all(g[r][c]==2 or (r,c) in obj_cells for r in range(H))]
    out=[row[:] for row in g]
    def splash(r,c,vertical):
        for dr in range(-2,3):
            for dc in range(-2,3):
                dist=abs(dr)+abs(dc)
                if dist==0 or dist>2: continue
                if vertical and dr==0 and abs(dc)==2: continue
                if (not vertical) and dc==0 and abs(dr)==2: continue
                rr,cc=r+dr,c+dc
                if 0<=rr<H and 0<=cc<W and out[rr][cc]!=3: out[rr][cc]=1
    for (r,c) in centers:
        on_h = r in hlines; on_v = c in vlines
        if on_h: # horizontal line -> vertical beams; splash line-axis vertical
            for d in (-1,1):
                rr=r+d
                while 0<=rr<H:
                    if out[rr][c]==3: rr+=d; continue
                    if g[rr][c]==2 and (rr,c) not in obj_cells:
                        splash(rr,c,True); rr+=d; continue
                    if g[rr][c]==0: out[rr][c]=1
                    rr+=d
        if on_v:
            for d in (-1,1):
                cc=c+d
                while 0<=cc<W:
                    if out[r][cc]==3: cc+=d; continue
                    if g[r][cc]==2 and (r,cc) not in obj_cells:
                        splash(r,cc,False); cc+=d; continue
                    if g[r][cc]==0: out[r][cc]=1
                    cc+=d
    return out

